// Editorial seed: indices refer only to the verified 23 October 2026 snapshot.
// Export is keyed by stable YouTube video ID; future syncs do not use indices.
import fs from 'node:fs';
const catalog=JSON.parse(fs.readFileSync('channel-catalog.json','utf8'));
const entries=[];
function guide(indices,heading,text){entries.push({indices,heading,facts:text.split('|').map(s=>s.trim())})}
guide([0,4,8],'Cell death and tissue response','[Necrosis] involves loss of membrane integrity and commonly provokes inflammation.|[Apoptosis] is regulated cell death with cellular fragmentation and clearance of apoptotic bodies.|[Coagulative necrosis] preserves tissue architecture initially and is typical of ischemic injury in most solid organs other than the brain.|[Liquefactive necrosis] is associated with brain infarction and many bacterial abscesses.|[Caseous necrosis] has a granular, cheese-like appearance and is classically associated with tuberculosis.');
guide([1],'Why material accumulates in cells','[Steatosis] is the accumulation of triglycerides within cells, especially hepatocytes.|[Lipofuscin] is a residual pigment associated with lipid peroxidation and cellular aging.|[Hemosiderin] stores iron and can be demonstrated with a Prussian blue stain.|[Carbon] particles may be retained in macrophages after inhalation; impaired clearance can produce tissue deposits.');
guide([2],'Amyloid deposition','[Amyloid] consists of extracellular deposits of misfolded proteins with a beta-pleated sheet configuration.|[Congo red] staining produces characteristic apple-green birefringence under polarized light.|[AL amyloid] is derived from immunoglobulin light chains and can accompany plasma-cell disorders.|[AA amyloid] derives from serum amyloid A and is associated with chronic inflammatory disease.');
guide([3],'Oxidative injury','[Reactive oxygen species] can damage membrane lipids, proteins, and nucleic acids.|[Superoxide dismutase] converts superoxide to hydrogen peroxide.|[Catalase] and glutathione peroxidase participate in hydrogen peroxide removal.|[Reperfusion] can intensify injury through oxidant generation and inflammatory activation after ischemia.');
guide([5,9],'Mechanisms of cell injury','[Hypoxemia] means reduced oxygen in arterial blood; it is distinct from reduced tissue perfusion.|[Ischemia] limits oxygen and nutrient delivery while impairing removal of metabolic waste.|[ATP depletion] impairs ion pumps and can produce cellular swelling.|[Irreversible injury] is associated with severe mitochondrial dysfunction and loss of membrane integrity.');
guide([6],'Adaptation versus injury','[Hypertrophy] means an increase in cell size.|[Hyperplasia] means an increase in cell number in a tissue capable of proliferation.|[Atrophy] means a reduction in cell size and sometimes cell number.|[Metaplasia] is replacement of one differentiated cell type by another better suited to a persistent stress.');
guide([7],'Recognizing pediatric rhythms','[Hemodynamic stability] determines the urgency of arrhythmia management.|[Sinus tachycardia] often reflects an underlying cause such as fever, pain, or hypovolemia.|[Supraventricular tachycardia] commonly presents as a rapid regular narrow-complex rhythm, but interpretation must account for age.|[Hypoxia] is an important reversible contributor to bradycardia in children.');
guide([10],'Pneumonia in children','[Pneumonia] is infection of lung parenchyma and may cause fever, cough, tachypnea, and increased work of breathing.|[Hypoxemia] and respiratory distress are important severity findings.|[Viral infection] is a frequent cause in young children; not every pneumonia requires antibacterial treatment.|[Age] and clinical severity influence diagnostic testing, likely pathogens, and disposition.');
guide([11],'Bronchiolitis fundamentals','[Bronchiolitis] is a viral lower-airway illness affecting small airways in infants and young children.|[Respiratory syncytial virus] is a common cause, although other viruses also produce bronchiolitis.|[Supportive care] focuses on oxygenation, hydration, and feeding assessment.|[Apnea] can be a presenting feature in very young infants.');
guide([12],'Peritonsillar infection','[Peritonsillar abscess] is a collection of pus adjacent to the tonsil.|[Trismus] and a muffled voice support the diagnosis in the appropriate setting.|[Uvular deviation] away from the affected side may be present.|[Airway compromise] is a major concern and requires urgent assessment.');
guide([13],'Deep neck space infection','[Retropharyngeal infection] may cause fever, neck stiffness, dysphagia, and airway symptoms.|[Contrast-enhanced CT] may help define a deep neck collection when the airway is stable and imaging is appropriate.|[Lemierre syndrome] involves septic thrombophlebitis of the internal jugular vein, often after oropharyngeal infection.|[Fusobacterium necrophorum] is a classic organism associated with Lemierre syndrome.');
guide([14],'Foreign body aspiration','[Sudden choking] followed by cough or unilateral wheeze suggests airway foreign body aspiration.|[Air trapping] can result from a partial ball-valve obstruction.|[Normal radiography] does not exclude an inhaled foreign body.|[Bronchoscopy] is used for definitive evaluation and removal when clinically indicated.');
guide([15],'Bacterial tracheitis','[Bacterial tracheitis] can cause severe upper-airway obstruction through inflammation and thick secretions.|[Staphylococcus aureus] is a recognized causative organism.|[Toxic appearance] and high fever may help distinguish the illness from uncomplicated viral croup.|[Airway management] takes priority when obstruction is suspected.');
guide([16],'Epiglottitis recognition','[Epiglottitis] is inflammation of supraglottic structures that can rapidly obstruct the airway.|[Drooling] and difficulty swallowing are important clinical clues.|[Tripod positioning] may reflect an attempt to improve airflow.|[Controlled airway assessment] is essential; unnecessary agitation and provocative examination may worsen obstruction.');
guide([17],'Croup recognition','[Subglottic edema] is a key mechanism in croup.|[Barking cough] and inspiratory stridor are characteristic clinical findings.|[Parainfluenza viruses] are common causes.|[Stridor at rest] indicates more significant obstruction than stridor only during agitation.');
guide([18],'Junctional rhythms','[AV junction] tissue can act as an escape pacemaker when sinus impulses fail or are not conducted.|[Retrograde P waves] may appear before, within, or after the QRS complex.|[Narrow QRS complexes] are common if ventricular conduction is otherwise normal.|[Clinical context] distinguishes a protective escape rhythm from an arrhythmia requiring treatment.');
guide([19],'Sinus bradycardia','[Sinus bradycardia] has a sinus P wave before each QRS with a slower-than-expected heart rate.|[Athletic conditioning] and sleep can produce physiologic slowing.|[Hypoperfusion] rather than the heart-rate number alone determines urgent clinical significance.|[Medication effects] and metabolic abnormalities are potentially reversible causes.');
guide([20],'Ventricular ectopy','[Premature ventricular contractions] originate in ventricular tissue before the next expected sinus beat.|[Wide QRS complexes] are typical because activation does not follow the usual ventricular conduction sequence.|[Compensatory pauses] often follow premature ventricular beats.|[Structural heart disease] and symptom burden influence evaluation.');
guide([21],'Rapid sequence intubation concepts','[Preoxygenation] increases the oxygen reserve before induction and apnea.|[Neuromuscular blockade] facilitates intubation but does not provide sedation or analgesia.|[Waveform capnography] is used to help confirm tracheal tube placement and monitor ventilation.|[Rescue oxygenation] planning is essential before attempting a difficult airway.');
guide([22],'Atrial ectopy','[Premature atrial contractions] arise from an atrial focus outside the sinus node.|[Abnormal P-wave morphology] can distinguish an ectopic atrial beat from a sinus beat.|[Narrow QRS complexes] are usual unless there is aberrant ventricular conduction.|[Blocked atrial beats] occur when a premature impulse reaches a refractory AV node.');
guide([23],'Extraglottic airway devices','[Supraglottic devices] establish a ventilatory pathway above the vocal cords.|[Rescue ventilation] is an important role when mask ventilation or tracheal intubation is difficult.|[Aspiration protection] is less complete than with a correctly positioned cuffed tracheal tube.|[Device position] and an adequate seal are essential to effective ventilation.');
guide([24],'Spinal motion restriction','[Motion restriction] aims to limit additional movement when spinal injury is suspected.|[Neurologic examination] documents motor and sensory function before and after movement when possible.|[Clinical assessment] guides selection of patients who need spinal precautions.|[Prolonged immobilization] can cause pressure injury and respiratory discomfort.');
guide([25],'Respiratory sinus arrhythmia','[Respiratory sinus arrhythmia] is cyclic variation in sinus rate with breathing.|[Inspiration] commonly increases heart rate while expiration slows it.|[Sinus P waves] remain present with the expected atrial morphology.|[Young healthy people] commonly show this benign variation.');
guide([26],'Bag-mask ventilation concepts','[Mask seal] is essential to limit leak during assisted ventilation.|[Airway positioning] improves patency and the delivery of breaths.|[Visible chest rise] helps assess whether ventilation is reaching the lungs.|[Excessive ventilation] can increase gastric inflation and impair venous return.');
guide([27],'Noninvasive positive pressure','[CPAP] applies a continuous positive airway pressure throughout the respiratory cycle.|[Bilevel ventilation] provides different inspiratory and expiratory pressures.|[Inspiratory pressure support] helps reduce work of breathing and improve ventilation.|[Inability to protect the airway] is an important limitation of noninvasive ventilation.');
guide([28,29,30],'Airway assessment and patency','[Tongue displacement] can obstruct the upper airway in an unconscious person.|[Jaw thrust] can help open the airway when cervical motion should be minimized.|[Oropharyngeal airways] are generally used only when the gag reflex is absent.|[Oxygenation] and ventilation must both be assessed because a patent airway alone does not guarantee adequate gas exchange.');
guide([31],'Scaphoid fracture essentials','[Anatomic snuffbox tenderness] after a fall on an outstretched hand raises suspicion of scaphoid injury.|[Initial radiographs] may be normal despite a fracture.|[Retrograde blood supply] makes proximal scaphoid injuries vulnerable to avascular necrosis.|[Nonunion] is an important complication of missed or unstable fractures.');
guide([32],'Wrist anatomy and injury','[Distal radioulnar joint] stability supports forearm pronation and supination.|[Triangular fibrocartilage complex] injuries can cause ulnar-sided wrist pain.|[Scapholunate ligament] disruption can alter carpal alignment.|[Neurovascular assessment] is part of evaluating any significant wrist injury.');
guide([33],'Rifaximin','[Rifaximin] is a poorly absorbed antibiotic acting mainly within the intestinal lumen.|[Bacterial RNA polymerase] is the pharmacologic target.|[Hepatic encephalopathy] recurrence prevention is an established use in appropriate patients.|[Systemic infection] generally requires an antibiotic with suitable systemic exposure rather than rifaximin.');
guide([34],'Lactulose','[Lactulose] is a nonabsorbable disaccharide metabolized by intestinal bacteria.|[Colonic acidification] favors trapping ammonia as ammonium.|[Osmotic laxation] contributes to stool passage and reduction of intestinal nitrogen burden.|[Diarrhea] and electrolyte disturbance can occur with excessive effect.');
guide([35,257],'Hepatic encephalopathy','[Hepatic encephalopathy] is brain dysfunction associated with liver insufficiency or portosystemic shunting.|[Asterixis] is a possible examination finding but is not specific to this condition.|[Precipitating factors] include infection, gastrointestinal bleeding, constipation, and medication effects.|[West Haven grading] describes clinical severity from subtle changes through coma.');
guide([36],'Ondansetron','[5-HT3 receptors] are blocked by ondansetron to reduce emetic signaling.|[Chemotherapy-associated nausea] is one common indication for this antiemetic class.|[QT prolongation] is an important cardiac adverse effect, especially in susceptible patients.|[Constipation] and headache are commonly reported adverse effects.');
guide([37,256],'Metoclopramide','[Dopamine D2 blockade] contributes to the antiemetic action of metoclopramide.|[Prokinetic activity] enhances upper gastrointestinal motility.|[Tardive dyskinesia] is a serious risk with prolonged exposure.|[Renal function] and indication affect dosing; a short video is not a substitute for current prescribing information.');
guide([38],'Gastroesophageal reflux','[Lower esophageal sphincter dysfunction] permits gastric contents to reflux into the esophagus.|[Heartburn] and regurgitation are typical symptoms.|[Dysphagia] is an alarm symptom requiring further assessment.|[Barrett esophagus] is a metaplastic complication associated with chronic reflux.');
guide([39,269],'H. pylori treatment principles','[Antibiotic resistance] is a key determinant of eradication regimen selection.|[Bismuth quadruple therapy] is a recommended empiric option in the ACG 2024 guidance when susceptibility is unknown.|[Clarithromycin susceptibility] should be established before using clarithromycin triple therapy under that guidance.|[Test of cure] is needed after eradication treatment; symptom relief alone does not prove eradication.');
guide([40],'Misoprostol','[Prostaglandin E1] is the endogenous mediator mimicked by misoprostol.|[Mucosal protection] increases through effects on mucus and bicarbonate secretion.|[Diarrhea] and abdominal cramping are common adverse effects.|[Uterine contraction] explains why pregnancy status and indication are crucial to safe use.');
guide([41],'Bismuth subsalicylate','[Bismuth] contributes local protective and antimicrobial effects in the gastrointestinal tract.|[Salicylate] exposure is relevant to allergy, interactions, and toxicity risk.|[Dark stools] and a dark tongue may occur and can be benign medication effects.|[Combination therapy] uses bismuth as one component of some H. pylori eradication regimens.');
guide([42],'Sucralfate','[Sucralfate] forms a protective complex that adheres to injured gastrointestinal mucosa.|[Local action] distinguishes it from agents that primarily suppress acid secretion.|[Constipation] is a recognized adverse effect.|[Drug binding] can reduce absorption of other medications taken at the same time.');
guide([43,236],'Proton pump inhibitors','[H+/K+-ATPase] is the gastric proton pump inhibited by this drug class.|[Parietal cells] are the gastric acid-secreting cells targeted by proton pump inhibitors.|[Acid suppression] supports healing of acid-related mucosal injury.|[Indication review] helps avoid continuing treatment without a clear ongoing reason.');
guide([44],'Histamine H2 antagonists','[H2 receptor blockade] reduces histamine-stimulated acid secretion in parietal cells.|[Famotidine] is an example of an H2 receptor antagonist.|[Cimetidine] has more prominent drug-interaction potential than several other drugs in the class.|[Renal clearance] is relevant to dose adjustment for many H2 antagonists.');
guide([45],'Antacids','[Neutralization] of existing gastric acid is the main action of antacids.|[Magnesium salts] can cause diarrhea.|[Aluminum salts] can cause constipation.|[Chelation] and changes in gastric pH can alter absorption of other medicines.');
guide([46],'Peptic ulcer disease foundations','[H. pylori] infection and NSAID exposure are major causes of peptic ulcer disease.|[Muscularis mucosae] penetration distinguishes an ulcer from a more superficial erosion.|[Gastrointestinal bleeding] and perforation are important complications.|[Cause-directed treatment] combines acid suppression with correction of the underlying driver.');
guide([47],'Oxygen therapy principles','[Oxygenation] refers to oxygen transfer into blood and is distinct from carbon dioxide clearance.|[Pulse oximetry] estimates arterial oxygen saturation but does not directly measure ventilation.|[Controlled oxygen delivery] allows adjustment to the patient’s target and clinical response.|[Hypercapnia risk] warrants careful monitoring in susceptible patients.');
guide([48],'Mucoactive medicines','[N-acetylcysteine] can break disulfide bonds within mucus.|[Guaifenesin] is classified as an expectorant.|[Carbocisteine] is a mucoregulating agent used in some settings.|[Underlying cause] of cough and sputum production remains central to assessment.');
guide([49],'Cough suppressants','[Dextromethorphan] is a centrally acting nonopioid antitussive.|[Codeine] has opioid effects and can depress respiration.|[Productive cough] may serve an airway-clearance function, so suppression is not always appropriate.|[Medication interactions] are important when dextromethorphan is combined with serotonergic agents.');
guide([50,51,60],'Asthma: inflammation and variable airflow','[Variable expiratory airflow limitation] is a defining physiologic feature of asthma.|[Inhaled corticosteroid-containing treatment] reduces exacerbation risk and is central to current GINA management.|[Inhaler technique] and adherence should be checked before escalating long-term treatment.|[Severe exacerbation] requires urgent assessment of respiratory effort, oxygenation, and response to therapy.');
guide([52],'Anti-IL-5 therapy','[Interleukin-5] supports eosinophil growth and survival.|[Mepolizumab] and reslizumab target IL-5 in selected patients with severe eosinophilic asthma.|[Phenotype assessment] helps determine whether biologic treatment is appropriate.|[Maintenance therapy] is the role of these biologics; they are not rescue bronchodilators.');
guide([53],'Omalizumab','[IgE] is the target of omalizumab.|[Allergic asthma] is an established indication in appropriately selected patients.|[Anaphylaxis] is an important potential adverse reaction.|[Biologic selection] depends on disease phenotype and eligibility criteria.');
guide([54],'Mast cell stabilization','[Cromolyn] reduces mast-cell mediator release.|[Prevention] rather than immediate bronchodilation is the pharmacologic role of mast-cell stabilizers.|[Ketotifen] also has antihistamine activity.|[Acute bronchospasm] is not rapidly reversed by cromolyn.');
guide([55],'Leukotriene modifiers','[Montelukast] blocks the cysteinyl leukotriene receptor.|[Zileuton] inhibits 5-lipoxygenase and reduces leukotriene synthesis.|[Bronchoconstriction] and mucus production are effects of cysteinyl leukotrienes.|[Neuropsychiatric effects] are an important safety concern with montelukast.');
guide([56],'Inhaled corticosteroids','[Airway inflammation] is reduced by inhaled corticosteroids.|[Oral candidiasis] is a local adverse effect.|[Mouth rinsing] after use can help reduce local adverse effects.|[Controller therapy] reduces future risk; most inhaled steroid products alone do not provide rapid rescue bronchodilation.');
guide([57],'Methylxanthines','[Theophylline] has bronchodilator activity and a narrow therapeutic index.|[Drug interactions] can significantly alter theophylline concentrations.|[Arrhythmias] and seizures are serious manifestations of toxicity.|[Concentration monitoring] may be necessary when these medicines are used.');
guide([58],'Ipratropium','[Muscarinic receptor blockade] reduces vagally mediated bronchoconstriction.|[Ipratropium] is a short-acting inhaled antimuscarinic.|[Dry mouth] is a common adverse effect.|[Adjunct therapy] with a short-acting beta agonist is useful in some acute severe asthma settings.');
guide([59],'Beta-2 agonists','[Beta-2 receptor stimulation] relaxes bronchial smooth muscle.|[Cyclic AMP] is an intracellular mediator of the bronchodilator response.|[Tremor] and tachycardia are recognized adverse effects.|[Hypokalemia] may occur through movement of potassium into cells.');
guide([61],'Fibrinolytic medicines','[Plasminogen activation] produces plasmin and promotes fibrin breakdown.|[Alteplase] is a tissue plasminogen activator used in selected thrombotic emergencies.|[Bleeding] is the major serious adverse effect.|[Eligibility assessment] must account for indication, timing, imaging, and contraindications.');
guide([62],'Low molecular weight heparin','[Antithrombin] mediates the anticoagulant effect of low molecular weight heparin.|[Factor Xa inhibition] predominates relative to thrombin inhibition in this class.|[Renal impairment] can increase exposure to some low molecular weight heparins.|[Heparin-induced thrombocytopenia] remains possible even though risk is lower than with unfractionated heparin.');
guide([63],'Heparin versus warfarin','[Unfractionated heparin] enhances antithrombin-mediated inhibition of clotting enzymes.|[Warfarin] interferes with vitamin K recycling and synthesis of vitamin K-dependent clotting factors.|[INR] is used to monitor warfarin anticoagulation.|[Onset of action] is faster with parenteral heparin than with warfarin.');
guide([64],'Bupropion','[Norepinephrine and dopamine] reuptake inhibition contributes to bupropion activity.|[Insomnia] and dry mouth are common adverse effects.|[Seizure risk] increases with higher exposure and susceptible clinical conditions.|[Smoking cessation] is one use of selected bupropion formulations.');
guide([65],'Sertraline','[Serotonin reuptake inhibition] is the principal action of sertraline.|[Gastrointestinal upset] and sexual dysfunction are recognized adverse effects.|[Serotonin syndrome] may occur with interacting serotonergic medicines.|[Abrupt discontinuation] can produce withdrawal symptoms after sustained treatment.');
guide([66],'Imipramine','[Tricyclic antidepressants] inhibit monoamine reuptake and have multiple receptor effects.|[Antimuscarinic effects] can cause dry mouth, urinary retention, and constipation.|[Orthostatic hypotension] can result from alpha-adrenergic blockade.|[Cardiac sodium-channel blockade] contributes to dangerous conduction abnormalities in overdose.');
guide([67],'Amphetamine','[Catecholamine signaling] is increased by amphetamine.|[Appetite suppression] and insomnia are common adverse effects.|[Blood pressure] and heart rate can increase.|[Misuse potential] is an important consideration in prescribing and monitoring.');
guide([68],'Atomoxetine','[Norepinephrine reuptake inhibition] is the main action of atomoxetine.|[ADHD] is a principal indication.|[Gastrointestinal symptoms] and appetite reduction may occur.|[Heart rate] and blood pressure should be considered during monitoring.');
guide([69,76],'Supporting bone healing','[Mechanical stability] and adequate blood supply support fracture union.|[Protein adequacy] is part of maintaining the nutritional resources needed for repair.|[Smoking] is associated with impaired healing and higher complication risk.|[Individual food claims] should be distinguished from evidence about overall nutrition, alcohol exposure, and systemic disease.');
guide([78],'Statin pharmacology','[HMG-CoA reductase] is the enzyme inhibited by statins.|[LDL receptor expression] increases in the liver, enhancing LDL clearance.|[Muscle symptoms] are a recognized adverse effect; severe rhabdomyolysis is uncommon.|[Cardiovascular risk reduction] is the clinical purpose of statin therapy in appropriate patients.');
guide([80,253],'NSAID pharmacology','[Cyclooxygenase inhibition] reduces prostaglandin production.|[Analgesia] and reduction of inflammation are major therapeutic effects.|[Gastrointestinal bleeding] is an important adverse effect.|[Kidney injury] can occur when prostaglandin-dependent renal perfusion is compromised.');
guide([81,82,83],'Amlodipine','[Dihydropyridine calcium-channel blockade] relaxes vascular smooth muscle.|[Peripheral edema] is a common adverse effect related to changes in microvascular pressure.|[Hypotension] can occur, especially in susceptible patients.|[Contraindications] should be distinguished from cautions; use the current product label rather than assuming every caution is an absolute prohibition.');
guide([84,87,190],'Orthopedic assessment essentials','[Neurovascular examination] should be documented during limb injury assessment.|[Orthogonal views] reduce the chance of missing displacement on radiographs.|[Joint alignment] must be checked alongside bony cortex and soft tissues.|[Associated injuries] can influence management even when the primary fracture appears straightforward.');
guide([94],'Sternoclavicular joint injury','[Posterior displacement] can threaten mediastinal structures.|[CT imaging] is useful for defining the direction and extent of displacement.|[Respiratory symptoms] or vascular compromise are important warning signs.|[Physeal injury] can mimic sternoclavicular dislocation in younger patients.');
guide([99],'Gabapentin','[Alpha-2-delta subunit] binding at voltage-gated calcium channels contributes to gabapentin activity.|[Neuropathic pain] and adjunctive seizure therapy are established uses.|[Somnolence] and dizziness are common adverse effects.|[Renal elimination] makes kidney function relevant to dosing.');
guide([100],'Levetiracetam','[SV2A] is the synaptic vesicle protein targeted by levetiracetam.|[Focal seizures] are among its treatment indications.|[Behavioral changes] such as irritability may occur.|[Renal clearance] is important when selecting a dose.');
guide([101],'Topiramate','[Multiple mechanisms] include effects on sodium channels, GABA signaling, and glutamate signaling.|[Cognitive slowing] is a notable adverse effect.|[Kidney stones] and metabolic acidosis can occur.|[Pregnancy risk] requires careful counselling and current prescribing guidance.');
guide([102],'Lamotrigine','[Voltage-gated sodium channels] are a major target of lamotrigine.|[Slow titration] helps reduce the risk of serious rash.|[Stevens-Johnson syndrome] is an uncommon but serious adverse reaction.|[Valproate] can increase lamotrigine exposure through inhibition of metabolism.');
guide([104],'Valproate','[Broad-spectrum antiseizure activity] allows use across several seizure types.|[Hepatotoxicity] and pancreatitis are serious adverse effects.|[Teratogenicity] is a major concern requiring specialist risk assessment.|[Thrombocytopenia] can occur and is relevant to monitoring.');
guide([105],'Carbamazepine','[Sodium-channel blockade] reduces repetitive neuronal firing.|[Enzyme induction] can lower concentrations of interacting medicines.|[Hyponatremia] is a recognized adverse effect.|[Serious skin reactions] have genetic associations that influence screening in relevant populations.');
guide([107],'Omphalocele','[Midline abdominal wall defect] at the umbilicus allows herniation of abdominal contents.|[Membranous sac] usually covers the herniated organs in omphalocele.|[Associated anomalies] are common and should be sought.|[Gastroschisis] differs by usually being paraumbilical and lacking a covering sac.');
guide([108],'Atelectasis on radiographs','[Volume loss] is the central radiographic clue to atelectasis.|[Fissure displacement] may point toward the collapsed lobe.|[Mediastinal shift] can occur toward a substantially collapsed lung.|[Compensatory hyperinflation] may be seen in unaffected lung.');
guide([109],'Pneumothorax imaging','[Visceral pleural line] may be visible with no peripheral lung markings beyond it.|[Deep sulcus sign] can suggest pneumothorax on a supine radiograph.|[Tension physiology] is a clinical emergency and treatment must not wait for imaging when strongly suspected.|[Pleural air] separates the lung from the chest wall.');
guide([110],'Systematic chest radiograph review','[Image quality] assessment includes projection, rotation, inspiration, and exposure.|[Airway position] and mediastinal contours are checked systematically.|[Lung fields] should be compared for asymmetry, opacity, and abnormal lucency.|[Pleural spaces] are reviewed for fluid and air.');
guide([111],'Seizure classification','[Focal onset] indicates a seizure beginning within networks in one hemisphere.|[Generalized onset] involves bilateral networks from the start.|[Provoked seizures] occur in association with an acute reversible insult and do not automatically establish epilepsy.|[Status epilepticus] is a neurologic emergency requiring prompt treatment.');
guide([118],'Parkinson disease pharmacology','[Levodopa] is converted to dopamine in the brain.|[Carbidopa] inhibits peripheral dopa decarboxylase and reduces peripheral levodopa metabolism.|[COMT inhibitors] can prolong levodopa effect.|[Dopamine agonists] directly stimulate dopamine receptors and may cause impulse-control disorders.');
guide([119],'Abdominal wall anatomy','[External oblique] is the most superficial of the three lateral flat abdominal muscles.|[Transversus abdominis] is the deepest of the three lateral muscle layers.|[Rectus sheath] surrounds the rectus abdominis with an arrangement that changes at the arcuate line.|[Linea alba] is the midline fibrous raphe.');
guide([120],'Gastroschisis','[Paraumbilical defect] is characteristic of gastroschisis, usually to the right of the umbilicus.|[Exposed bowel] lacks the membranous sac typical of omphalocele.|[Fluid and heat loss] are major early concerns.|[Bowel assessment] is important because intestinal complications may coexist.');
guide([127],'Meconium aspiration','[Airway obstruction] and chemical inflammation contribute to meconium aspiration syndrome.|[Surfactant dysfunction] can worsen respiratory mechanics.|[Persistent pulmonary hypertension] may complicate severe disease.|[Respiratory support] is individualized to oxygenation and ventilation needs.');
guide([128],'Neonatal sepsis','[Nonspecific signs] may include feeding difficulty, temperature instability, and respiratory distress.|[Blood cultures] help identify the pathogen when obtained appropriately.|[Early-onset infection] is often associated with maternal or perinatal exposure.|[Prompt evaluation] matters because deterioration can be rapid.');
guide([129],'Neonatal cyanosis','[Central cyanosis] reflects reduced arterial oxygenation or abnormal hemoglobin rather than isolated peripheral vasoconstriction.|[Cardiac disease] and pulmonary disease are major diagnostic categories.|[Preductal and postductal saturations] can provide useful physiologic clues.|[Perfusion assessment] is essential because cyanosis and shock may coexist.');
guide([130,131],'Hernia evaluation','[Reducible hernia] can return through the defect into its usual compartment.|[Incarceration] means the contents are trapped and cannot be reduced.|[Strangulation] means compromised blood supply and requires urgent surgical assessment.|[Painful irreducible swelling] with obstructive or systemic symptoms is concerning.');
guide([137],'Alcohol-associated hepatitis','[Inflammatory liver injury] related to alcohol exposure can present with jaundice.|[AST predominance] over ALT is common but is not diagnostic by itself.|[Severity assessment] considers synthetic dysfunction and complications rather than enzyme levels alone.|[Nutritional support] and alcohol cessation are core components of care.');
guide([139],'Acute liver failure','[Coagulopathy] and encephalopathy are central features of acute liver failure in the appropriate clinical setting.|[Acetaminophen toxicity] is an important cause.|[Urgent specialist assessment] is needed because deterioration and transplant need can develop rapidly.|[Cerebral edema] is a serious potential complication.');
guide([144],'Interpreting liver tests','[Aminotransferases] indicate hepatocellular injury rather than directly measuring liver function.|[Alkaline phosphatase] may rise in cholestasis but also has nonhepatic sources.|[INR] and albumin provide information about synthetic function, with important confounders.|[Bilirubin fractionation] helps distinguish patterns of production, processing, and excretion.');
guide([147],'CNS pharmacology foundations','[Receptor selectivity] helps explain both therapeutic and adverse effects.|[Blood-brain barrier penetration] influences central drug exposure.|[Tolerance] is reduced response after repeated exposure.|[Withdrawal] may follow abrupt cessation of certain drugs after sustained use.');
guide([148],'Estimating burn extent','[Total body surface area] estimates generally include partial- and full-thickness burns, not simple superficial erythema.|[Lund-Browder chart] adjusts body proportions for age.|[Rule of nines] is a rapid adult estimation method.|[Hand-based estimates] require a consistent convention because palm alone and the entire palmar hand are not identical areas.');
guide([151],'Fourth-degree burns','[Deep tissue extension] beyond skin into muscle, tendon, or bone defines this severe injury category.|[Tissue viability] must be assessed beyond the visible surface.|[Specialist burn care] is required for these extensive injuries.|[Reconstruction] may involve complex surgery depending on the structures damaged.');
guide([152],'Full-thickness burns','[Entire dermis] destruction is characteristic of full-thickness burns.|[Leathery appearance] may be present, with variable color.|[Reduced sensation] can occur because cutaneous nerves are damaged.|[Surgical assessment] is often needed because spontaneous healing across large areas is limited.');
guide([153],'Partial-thickness burns','[Dermal involvement] distinguishes partial-thickness injury from a superficial epidermal burn.|[Blistering] is a common finding.|[Depth] influences pain, capillary refill, healing time, and scarring.|[Reassessment] matters because burn depth can evolve.');
guide([154],'Superficial burns','[Epidermis] is the main layer involved in a superficial burn.|[Erythema] reflects increased blood flow in the affected skin.|[Pain] is common because sensory nerves remain intact.|[Blanching] is usually preserved.');
guide([155],'Intravenous fluid concepts','[Crystalloids] contain small solutes that distribute within extracellular compartments according to their composition.|[Balanced solutions] have electrolyte and buffer compositions designed to reduce chloride loading relative to saline.|[Dextrose metabolism] makes dextrose-in-water solutions behave differently from their initial bag osmolarity.|[Fluid reassessment] should consider perfusion, urine output, electrolytes, and overload risk.');
guide([156],'Membranous nephropathy','[Subepithelial immune deposits] are a defining ultrastructural finding.|[Nephrotic syndrome] is a common presentation.|[PLA2R antibodies] are associated with many primary cases.|[Secondary causes] include selected infections, autoimmune disorders, drugs, and malignancies.');
guide([157],'Focal segmental glomerulosclerosis','[Focal] means some glomeruli are affected.|[Segmental] means only part of an affected glomerulus is scarred.|[Podocyte injury] is central to the disease process.|[Proteinuria] can be substantial and may produce nephrotic syndrome.');
guide([158],'Minimal change disease','[Foot process effacement] is the characteristic electron-microscopic finding.|[Light microscopy] may show little or no obvious abnormality.|[Nephrotic syndrome] is a typical presentation, especially in children.|[Corticosteroid responsiveness] is common, although relapse may occur.');
guide([159],'Nephrotic syndrome','[Heavy proteinuria] results from altered glomerular filtration barrier function.|[Hypoalbuminemia] contributes to edema.|[Hyperlipidemia] commonly accompanies nephrotic syndrome.|[Thrombosis risk] is increased in many nephrotic conditions.');
guide([160],'Grafts and flaps','[Skin grafts] are transferred without their own intact blood supply.|[Flaps] retain or reestablish a vascular supply as part of transfer.|[Recipient bed vascularity] is crucial for graft survival.|[Reconstruction choice] depends on tissue loss, exposed structures, and blood supply.');
guide([161],'Hypertrophic and keloid scars','[Hypertrophic scars] remain within the boundaries of the original wound.|[Keloids] extend beyond the original injury margins.|[Excess collagen deposition] contributes to both conditions.|[Recurrence] is an important issue in keloid treatment.');
guide([162],'Infectious mononucleosis','[Epstein-Barr virus] is the classic cause of infectious mononucleosis.|[Posterior cervical lymphadenopathy] is a typical examination finding.|[Atypical lymphocytes] are largely reactive T cells in this setting.|[Splenic enlargement] raises concern about rupture with contact activity.');
guide([163],'Portal hypertension','[Increased portal pressure] results from increased resistance, increased flow, or both.|[Cirrhosis] is a common cause of intrahepatic resistance.|[Varices] develop through portosystemic collateral pathways.|[Ascites] is a common complication of advanced portal hypertensive disease.');
guide([164],'Pneumonia severity assessment','[CURB-65] incorporates confusion, urea, respiratory rate, blood pressure, and age.|[Clinical judgment] remains necessary because a score cannot capture every risk.|[Oxygenation] and ability to maintain oral intake influence disposition.|[Comorbidity] and social support are additional considerations.');
guide([165],'Wound healing','[Primary intention] describes healing of closely approximated wound edges.|[Secondary intention] involves filling a larger tissue defect with granulation tissue and contraction.|[Fibroblasts] produce extracellular matrix during repair.|[Remodeling] changes collagen organization and tensile strength over time.');
guide([166],'Water balance disorders','[Diabetes insipidus] causes impaired urinary concentration from deficient vasopressin action.|[SIADH] produces inappropriate water retention and hypotonic hyponatremia in the appropriate setting.|[Serum osmolality] helps interpret disorders of water balance.|[Urine osmolality] shows whether the kidney is appropriately diluting or concentrating urine.');
guide([167],'Burkitt lymphoma','[MYC dysregulation] is central to Burkitt lymphoma.|[Starry-sky pattern] results from macrophages scattered among rapidly proliferating tumor cells.|[High proliferation rate] is a characteristic feature.|[Tumor lysis syndrome] is an important risk during treatment.');
guide([168],'Pregnancy dating','[Last menstrual period] can provide an initial estimate when cycle dates are reliable.|[First-trimester ultrasound] is useful for establishing gestational age.|[Cycle variation] can reduce the accuracy of menstrual dating alone.|[Estimated due date] is an estimate rather than a guaranteed delivery date.');
guide([169],'Spinal cord injury classification','[Motor testing] evaluates key muscle groups systematically.|[Sensory testing] assesses light touch and pinprick in defined dermatomes.|[Sacral sparing] is central to distinguishing complete from incomplete injury.|[Neurologic level] is determined by standardized examination rather than imaging alone.');
guide([170],'Serum-ascites albumin gradient','[SAAG] is serum albumin minus ascitic fluid albumin, ideally measured close in time.|[Portal hypertension] is suggested by a gradient of at least 1.1 g/dL in the appropriate setting.|[Ascitic protein] adds information beyond the gradient.|[Diagnostic paracentesis] also evaluates cell count and infection when indicated.');
guide([193],'Receptor antagonists','[Competitive antagonists] compete with agonists for the same binding site.|[Surmountable antagonism] can be overcome by increasing agonist concentration.|[Reduced maximal response] may occur with irreversible or noncompetitive antagonism.|[Receptor reserve] can modify the observed dose-response pattern.');
guide([194],'Dose-response relationships','[Potency] describes the dose or concentration needed to produce a specified effect.|[Efficacy] describes the maximum achievable effect.|[Graded responses] quantify effect magnitude in a biological system.|[Quantal responses] describe whether a defined effect occurs across a population.');
guide([196],'Drug elimination','[Clearance] is the volume of plasma effectively cleared of a drug per unit time.|[Half-life] is the time required for concentration to fall by half under the specified conditions.|[First-order elimination] removes a constant fraction per unit time.|[Zero-order elimination] removes an approximately constant amount per unit time when capacity is saturated.');
guide([197],'Drug metabolism','[Phase I reactions] include oxidation, reduction, and hydrolysis.|[Phase II reactions] commonly conjugate a drug or metabolite with another molecule.|[Enzyme induction] can increase metabolism of susceptible drugs.|[Enzyme inhibition] can increase exposure to a drug cleared by the inhibited pathway.');
guide([198],'Drug distribution','[Volume of distribution] relates the amount of drug in the body to its plasma concentration.|[Protein binding] influences the unbound drug fraction.|[Tissue binding] can produce a large apparent volume of distribution.|[Perfusion] affects how quickly drugs reach different organs.');
guide([199],'Drug absorption','[Bioavailability] is the fraction of an administered dose reaching systemic circulation unchanged.|[First-pass metabolism] can reduce oral bioavailability.|[Ionization] influences membrane passage and depends on pH and pKa.|[Intravenous administration] delivers drug directly to systemic circulation.');
guide([202],'Urinary antimicrobial agents','[Nitrofurantoin] concentrates in urine and is used for selected lower urinary tract infections.|[Fosfomycin] inhibits an early step in bacterial cell-wall synthesis.|[Methenamine] produces formaldehyde in sufficiently acidic urine.|[Upper urinary infection] requires adequate renal-tissue and systemic drug exposure.');
guide([203],'Metronidazole','[Reactive metabolites] of metronidazole damage microbial DNA.|[Anaerobic organisms] are important targets.|[Protozoal infections] are additional indications.|[Peripheral neuropathy] is a recognized risk with prolonged exposure.');
guide([204],'Sulfonamides','[Folate synthesis] is inhibited by sulfonamides in susceptible bacteria.|[Dihydropteroate synthase] is the enzyme target.|[Trimethoprim] blocks a later step and provides sequential pathway inhibition.|[Hypersensitivity] is an important adverse-effect category.');
guide([205,206],'Fluoroquinolones','[DNA gyrase] and topoisomerase IV are bacterial enzyme targets.|[Ciprofloxacin] and levofloxacin are examples with differing spectra.|[Tendinopathy] is a serious class safety concern.|[Cation binding] can reduce oral absorption when taken with certain antacids or supplements.');
guide([207],'Linezolid','[50S ribosomal subunit] binding inhibits bacterial protein synthesis.|[Resistant gram-positive infections] are an important use of linezolid.|[Myelosuppression] can occur, especially with prolonged exposure.|[Serotonergic interactions] require review because linezolid has monoamine oxidase-inhibiting activity.');
guide([208],'Quinupristin and dalfopristin','[Streptogramins] inhibit bacterial protein synthesis at the 50S ribosomal subunit.|[Synergy] between the two components improves antibacterial activity.|[Enterococcus faecium] may be susceptible, whereas E. faecalis is intrinsically resistant.|[Arthralgia] and myalgia are notable adverse effects.');
guide([209],'Clindamycin','[50S ribosomal subunit] binding inhibits bacterial protein synthesis.|[Anaerobic activity] is useful in selected infections, subject to local resistance.|[Clostridioides difficile infection] is a major adverse-effect concern.|[Inducible resistance] should be considered in relevant staphylococcal isolates.');
guide([211],'Tigecycline','[Glycylcycline] is the antibiotic class of tigecycline.|[30S ribosomal subunit] binding inhibits protein synthesis.|[Nausea] and vomiting are common adverse effects.|[Low serum concentrations] limit its suitability for some bloodstream infections.');
guide([212],'Tetracyclines','[30S ribosomal subunit] binding interferes with aminoacyl-tRNA attachment.|[Doxycycline] is an example of this class.|[Photosensitivity] is a recognized adverse effect.|[Chelation] with polyvalent cations can reduce absorption.');
guide([213,265,267,268],'Macrolides','[50S ribosomal subunit] binding inhibits bacterial protein synthesis.|[Erythromycin] is a macrolide antibiotic.|[QT prolongation] is a relevant cardiac safety concern.|[Drug interactions] vary by agent; erythromycin and clarithromycin have notable CYP3A interaction potential.|[Cholestatic liver injury] is a recognized adverse reaction to some macrolides.');
guide([214,271,272,273,274,275,276],'Aminoglycosides','[30S ribosomal subunit] binding leads to errors in bacterial protein synthesis.|[Oxygen-dependent uptake] limits activity against anaerobic organisms.|[Nephrotoxicity] and ototoxicity are major adverse effects.|[Gentamicin] and amikacin are examples of aminoglycosides.|[Renal function] and drug exposure are important monitoring considerations.');
guide([215],'Protein synthesis inhibitors','[Bacterial ribosomes] provide targets distinct from mammalian cytoplasmic ribosomes.|[30S subunit] inhibitors include aminoglycosides and tetracyclines.|[50S subunit] inhibitors include macrolides and clindamycin.|[Resistance mechanisms] include target modification, efflux, and drug inactivation.');
guide([216,277,278],'Glycopeptides','[D-Ala-D-Ala binding] interferes with bacterial cell-wall synthesis.|[Vancomycin] is a glycopeptide used against susceptible gram-positive organisms.|[Infusion-related reactions] can occur with vancomycin and are distinct from some true allergic reactions.|[Renal monitoring] is important during systemic treatment.');
guide([217,279],'Carbapenems and monobactams','[Beta-lactam antibiotics] interfere with peptidoglycan cross-linking.|[Carbapenems] have broad antibacterial activity but are not active against every resistant organism.|[Aztreonam] primarily covers susceptible aerobic gram-negative bacteria.|[Resistance testing] is important because carbapenemases can inactivate these agents.');
guide([218,219],'Cephalosporin overview','[Penicillin-binding proteins] are targets of cephalosporins.|[Generation labels] summarize patterns but do not replace knowledge of individual drug spectra.|[Enterococci] are intrinsically resistant to cephalosporins.|[Hypersensitivity] history and side-chain similarity influence allergy assessment.');
guide([222,288],'Cell-wall active antibiotics','[Peptidoglycan] is a major structural component of the bacterial cell wall.|[Beta-lactams] bind penicillin-binding proteins and impair cross-linking.|[Glycopeptides] bind peptidoglycan precursors.|[Beta-lactamases] are enzymes that can inactivate susceptible beta-lactam drugs.');
guide([224,292,293,294,295],'Antibiotic selection fundamentals','[Empiric therapy] is selected before the causative organism and susceptibility are fully known.|[Culture results] can guide narrowing or changing treatment.|[Source control] may be necessary in addition to antimicrobial therapy.|[Combination therapy] is used for specific indications such as broad initial coverage or synergy, rather than automatically for every infection.|[Viral infections] do not respond to antibacterial drugs.');
guide([225],'Osmotic diuretics','[Mannitol] increases tubular fluid osmolality and reduces water reabsorption.|[Glomerular filtration] is necessary for mannitol to enter the tubular lumen.|[Volume expansion] can occur initially and may worsen pulmonary edema.|[Electrolyte disturbances] are important adverse effects.');
guide([226],'Carbonic anhydrase inhibition','[Acetazolamide] inhibits carbonic anhydrase.|[Bicarbonate excretion] increases as proximal tubular reabsorption falls.|[Metabolic acidosis] is an expected pharmacologic consequence.|[Altitude illness] prevention is one indication in selected circumstances.');
guide([227],'Potassium-sparing diuretics','[Spironolactone] antagonizes mineralocorticoid receptors.|[Amiloride] blocks epithelial sodium channels in the distal nephron.|[Hyperkalemia] is a central safety concern.|[Gynecomastia] can occur with spironolactone because of endocrine receptor effects.');
guide([228],'Thiazide diuretics','[Sodium-chloride cotransporter] inhibition occurs in the distal convoluted tubule.|[Calcium reabsorption] is increased relative to loop diuretics.|[Hyponatremia] and hypokalemia are recognized adverse effects.|[Hyperuricemia] can exacerbate gout in susceptible patients.');
guide([230],'Diuretic foundations','[Nephron site] determines much of a diuretic’s mechanism and electrolyte effects.|[Loop diuretics] act in the thick ascending limb.|[Thiazides] act in the distal convoluted tubule.|[Volume status] and electrolytes must be reassessed during treatment.');
guide([231],'Selective alpha blockers','[Alpha-1 blockade] relaxes vascular and lower urinary tract smooth muscle.|[Prazosin] and doxazosin can cause orthostatic hypotension.|[Tamsulosin] has relative selectivity for receptors relevant to urinary outflow.|[Yohimbine] differs by antagonizing alpha-2 receptors.');
guide([232],'Nonselective alpha blockers','[Phenoxybenzamine] produces irreversible alpha-adrenergic blockade.|[Phentolamine] is a reversible nonselective alpha antagonist.|[Pheochromocytoma] is an important clinical context for alpha blockade.|[Reflex tachycardia] and orthostatic hypotension may occur.');
guide([233],'Odontoid fracture classification','[Type I] involves the odontoid tip.|[Type II] involves the base of the odontoid and has greater nonunion concern.|[Type III] extends into the body of C2.|[Stability] and patient factors affect treatment selection.');
guide([235],'Propranolol','[Nonselective beta blockade] affects both beta-1 and beta-2 receptors.|[Bronchospasm] is a concern in susceptible patients.|[Bradycardia] can occur from cardiac beta blockade.|[Abrupt withdrawal] after chronic use may produce rebound sympathetic effects.');
guide([237],'Celecoxib','[COX-2 inhibition] is relatively selective with celecoxib.|[Analgesic activity] results from reduced prostaglandin production.|[Cardiovascular risk] remains relevant despite COX-2 selectivity.|[Renal adverse effects] remain possible, as with other NSAIDs.');
guide([238],'Danis-Weber classification','[Type A] fibular fractures are below the syndesmosis.|[Type B] fractures are at the syndesmotic level.|[Type C] fractures are above the syndesmosis.|[Medial injury] and syndesmotic stability affect management beyond the classification letter.');
guide([239],'Tibial plateau fractures','[Schatzker classification] organizes tibial plateau fracture patterns.|[Articular depression] can impair joint congruity.|[Bicondylar injury] involves both medial and lateral plateaus.|[Soft tissue condition] is important in planning fixation.');
guide([240,241,242,254],'Sutures and needle handling','[Absorbable sutures] lose tensile strength and are broken down over time.|[Monofilament sutures] consist of a single strand.|[Cutting needles] are suited to penetrating tougher tissues such as skin.|[Taper-point needles] separate rather than cut tissue and are used in many softer tissues.|[Needle control] depends on appropriate instrument grip and controlled passage through tissue.');
guide([243],'Acute pancreatitis','[Pancreatic inflammation] typically produces upper abdominal pain and may cause systemic illness.|[Lipase elevation] supports the diagnosis in the appropriate context.|[Gallstones] and alcohol are common etiologic categories.|[Severity assessment] includes organ failure and complications rather than a score alone.');
guide([244],'Acute appendicitis','[Right lower quadrant tenderness] is a common finding.|[Pain migration] from a central location to the right lower quadrant can occur.|[Alvarado score] combines clinical features and laboratory findings to support risk assessment.|[Imaging] and clinical reassessment help resolve diagnostic uncertainty.');
guide([245],'Acute coronary syndromes','[Myocardial ischemia] occurs when oxygen supply is insufficient for myocardial demand.|[ECG] is an early essential investigation in suspected acute coronary syndrome.|[Troponin] indicates myocardial injury but must be interpreted with clinical evidence.|[Reperfusion] is time-critical for eligible patients with acute coronary occlusion.');
guide([246],'Septic arthritis','[Joint infection] can rapidly damage articular cartilage.|[Synovial fluid analysis] is central to evaluation when joint infection is suspected.|[Kocher criteria] estimate likelihood in selected pediatric hip presentations but are not definitive.|[Drainage] and appropriate antimicrobial therapy are important treatment principles.');
guide([247],'Intertrochanteric fracture patterns','[Intertrochanteric fractures] occur in the proximal femur between the trochanters.|[Posteromedial support] contributes to fracture stability.|[Comminution] can increase mechanical instability.|[Evans-Jensen classification] describes patterns relevant to stability and fixation planning.');
guide([248],'Garden classification','[Garden I] is an incomplete or valgus-impacted femoral neck fracture.|[Garden II] is complete but undisplaced.|[Garden III] is complete and partially displaced.|[Garden IV] is completely displaced.|[Femoral head perfusion] is a major concern in displaced intracapsular fractures.');
guide([249],'Posterior hip dislocation','[Posterior displacement] is a common traumatic hip dislocation pattern.|[Sciatic nerve assessment] is important before and after reduction.|[Associated fractures] affect classification and management.|[Avascular necrosis] is a significant later complication.');
guide([250],'Pipkin classification','[Type I] femoral head fractures are below the fovea.|[Type II] fractures are above the fovea.|[Type III] includes an associated femoral neck fracture.|[Type IV] includes an associated acetabular fracture.');
guide([251],'Acromioclavicular injury','[Acromioclavicular ligaments] and coracoclavicular ligaments contribute to joint stability.|[Rockwood classification] describes increasing and differing patterns of displacement and soft-tissue injury.|[Posterior displacement] characterizes a type IV injury.|[Functional demands] and injury pattern influence treatment decisions.');
guide([252],'Glasgow Coma Scale','[Eye opening] is one of the three GCS components.|[Verbal response] is assessed alongside eye and motor responses.|[Motor response] has the largest numerical range of the three components.|[Component reporting] is more informative than a total score alone when factors such as intubation affect testing.');
guide([255,261],'Aspirin and salicylates','[Irreversible cyclooxygenase inhibition] explains aspirin’s prolonged platelet effect.|[Thromboxane A2] production is reduced in platelets.|[Mixed acid-base disturbance] in toxicity may include respiratory alkalosis and metabolic acidosis.|[Tinnitus] is a classic symptom of salicylate toxicity.');
guide([258],'MELD score concepts','[Liver disease severity] is quantified by MELD-based systems to support allocation decisions.|[Bilirubin] and INR reflect important aspects of hepatic dysfunction.|[Creatinine] contributes information about kidney function.|[Score version] matters because MELD, MELD-Na, and MELD 3.0 use different inputs and calculations.');
guide([259],'Child-Pugh classification','[Bilirubin] and albumin are laboratory components.|[INR] or prothrombin-time prolongation contributes to the score.|[Ascites] and encephalopathy are clinical components.|[Class A] represents the lowest score category, with classes B and C indicating greater severity.');
guide([260],'Acetaminophen toxicity','[NAPQI] is a reactive metabolite responsible for much of the hepatic injury in overdose.|[Glutathione] normally detoxifies NAPQI.|[N-acetylcysteine] restores detoxification capacity and is an antidote used under clinical guidance.|[Time since ingestion] and exposure pattern are essential to interpreting acetaminophen concentrations.');
guide([262,263],'Acute kidney injury','[Creatinine rise] and reduced urine output are key functional markers of acute kidney injury.|[Baseline kidney function] is necessary to interpret changes appropriately.|[KDIGO 2012 criteria] include a creatinine rise of at least 0.3 mg/dL within 48 hours or at least 1.5 times baseline within seven days.|[Oliguria] below 0.5 mL/kg/hour for six hours is another criterion in that framework.|[Staging] uses the more severe applicable creatinine or urine-output criterion.');
guide([264],'Telithromycin','[Ketolides] are related to macrolides and inhibit bacterial protein synthesis.|[Telithromycin] has important safety restrictions that limit its clinical role.|[Hepatotoxicity] is a serious concern.|[Myasthenia gravis] is a major contraindication associated with potentially severe worsening.');
guide([266],'Antibiotic combinations: avoid blanket rules','[Clinical indication] determines whether a beta-lactam and a macrolide should be combined.|[Community-acquired pneumonia] is one setting in which such combinations may be recommended.|[Laboratory antagonism] does not automatically establish a universal clinical contraindication.|[Current guidelines] and patient factors should take precedence over a blanket prohibition in a video title.');
guide([270],'Tuberculosis treatment principles','[Combination therapy] reduces selection of resistant organisms.|[Drug susceptibility] determines the appropriate regimen.|[Rifampicin] and isoniazid are key drugs in traditional drug-susceptible TB regimens.|[Treatment duration] depends on regimen, resistance, site of disease, and current guidance.');
guide([280],'Aztreonam','[Monobactam] is the beta-lactam subclass of aztreonam.|[Aerobic gram-negative bacteria] are its main susceptible targets.|[Anaerobes] are not covered by aztreonam.|[Ceftazidime side-chain similarity] is relevant when evaluating certain beta-lactam allergies.');
guide([281],'Anti-MRSA cephalosporins','[Ceftaroline] has activity against MRSA through binding altered penicillin-binding proteins.|[PBP2a] is the altered target associated with methicillin resistance.|[Individual agent spectrum] matters more than a generation label alone.|[Pseudomonas coverage] should not be assumed for ceftaroline.');
guide([282],'Fourth-generation cephalosporins','[Cefepime] is a fourth-generation cephalosporin.|[Pseudomonas aeruginosa] may be susceptible, depending on local resistance.|[Renal impairment] can increase cefepime exposure.|[Neurotoxicity] is an important adverse effect when exposure is excessive.');
guide([283],'Third-generation cephalosporins','[Ceftriaxone] and cefotaxime are commonly used third-generation agents.|[Ceftazidime] differs through antipseudomonal activity.|[Spectrum differences] mean agents within a generation are not interchangeable.|[Beta-lactamase resistance] varies and can be overcome by extended-spectrum beta-lactamases.');
guide([284],'Second-generation cephalosporins','[Cefuroxime] is a second-generation cephalosporin.|[Cefoxitin] is a cephamycin with useful anaerobic activity in selected settings.|[Agent-specific coverage] is essential because not every drug in this group covers the same organisms.|[Susceptibility testing] helps guide treatment when resistance is possible.');
guide([285],'First-generation cephalosporins','[Cefazolin] is widely used for surgical prophylaxis in appropriate procedures.|[Cephalexin] is an oral first-generation cephalosporin.|[Methicillin-susceptible staphylococci] are commonly covered.|[MRSA] is not reliably covered by these agents.');
guide([286,287],'Penicillin allergy assessment','[Reaction history] should distinguish intolerance, immediate allergy, and severe delayed reactions.|[Side-chain similarity] influences cross-reactivity between beta-lactam drugs.|[Allergy testing] or supervised challenge may clarify selected low-risk histories.|[Severe delayed reactions] require a different approach from uncomplicated remote rash histories.');
guide([289],'Piperacillin-tazobactam','[Piperacillin] is an antipseudomonal penicillin.|[Tazobactam] inhibits selected beta-lactamases.|[Broad-spectrum activity] includes many gram-negative and anaerobic organisms but does not guarantee activity against every resistant isolate.|[Renal function] affects dose selection.');
guide([290,291],'Penicillin families','[Penicillin G] is a natural penicillin active against selected susceptible organisms.|[Aminopenicillins] include amoxicillin and ampicillin.|[Antistaphylococcal penicillins] are designed to resist staphylococcal penicillinase.|[Beta-lactamase production] is one mechanism of penicillin resistance.');
guide([296],'Gram stain and bacterial structure','[Gram-positive bacteria] have a thick peptidoglycan layer and usually retain crystal violet.|[Gram-negative bacteria] have an outer membrane containing lipopolysaccharide.|[Gram stain] is an early classification tool rather than a complete susceptibility test.|[Outer membrane permeability] influences antibiotic entry.');
guide([297],'IV cannula sizing','[Gauge number] is inversely related to cannula diameter.|[Larger internal diameter] generally supports greater flow under otherwise similar conditions.|[Catheter length] also affects resistance to flow.|[Device labeling] should be checked rather than relying only on a color mnemonic.');
guide([298],'Ceftriaxone and calcium','[Calcium-ceftriaxone precipitation] can occur when incompatible intravenous products are combined.|[Neonates] have particularly important restrictions even when separate infusion lines are considered.|[Compatible flushing] and timing rules for older patients depend on product labeling and local policy.|[Oral calcium] is not equivalent to an intravenous calcium-containing infusion in this interaction.');
const output={};
for(const entry of entries){for(const index of entry.indices){const v=catalog.videos[index];if(!v)throw Error('Missing index '+index);const facts=entry.facts;const pool=facts.map(f=>f.match(/\[([^\]]+)\]/)[1]);const questions=facts.slice(0,3).map((fact,i)=>{const answer=fact.match(/\[([^\]]+)\]/)[1];let options=[answer,...pool.filter(x=>x!==answer&&!fact.toLowerCase().includes(x.toLowerCase())).slice(0,3)];if(options.length<4)options=[answer,...pool.filter(x=>x!==answer).slice(0,3)];const shift=(index+i)%4;for(let n=0;n<shift;n++)options.push(options.shift());return {prompt:'Using the term from the notes, complete this statement: '+fact.replace(/\[[^\]]+\]/,'________'),options,answer,explanation:fact.replace(/[\[\]]/g,'')}});output[v.id]={heading:entry.heading,notes:[{type:'h2',text:entry.heading},{type:'p',text:'A concise, newly authored revision guide for this topic. Use the video for the instructor’s full explanation; these notes do not claim to transcribe it.'},...facts.map(text=>({type:'li',text:text.replace(/[\[\]]/g,'')})),{type:'h3',text:'Active recall'},{type:'p',text:'After watching, explain the key mechanism in your own words. Identify one distinguishing feature and one important limitation or complication, then answer the questions below.'}],questions};}}
fs.writeFileSync('study-guides.json',JSON.stringify(output,null,2));console.log('Authored guides:',Object.keys(output).length);

